typedef struct {
  rand bit [31:0] base_addr;
  rand bit [31:0] limit_addr;
} region_s;

class MemoryMap;
  rand region_s regions[];

  constraint c_size {regions.size() inside {[4 : 8]};}

  constraint c_bounds {
    foreach (regions[i]) {
      regions[i].base_addr inside {[32'h0000_0000 : 32'h7FFF_FFFF]};
      regions[i].limit_addr inside {[32'h0000_0000 : 32'h7FFF_FFFF]};
    }
  }

  constraint c_span {foreach (regions[i]) regions[i].base_addr < regions[i].limit_addr;}

  constraint c_align {
    foreach (regions[i]) {
      (regions[i].limit_addr - regions[i].base_addr + 1) % 32'h1000 == 0;
      regions[i].base_addr % 32'h1000 == 0;
    }
  }

  constraint c_order {
    foreach (regions[i]) {
      if (i == 0) {
        regions[i].base_addr inside {[32'h0000_0000 : 32'h7FFF_FFFF]};
      } else {
        regions[i].base_addr > regions[i-1].limit_addr;
      }
    }
  }
endclass

