class ThermalPowerFuzzer;
  rand bit [3:0] core_power[3][3];

  constraint c_range {
    foreach (core_power[i, j])
    core_power[i][j] inside {[1 : 9]};
  }

  constraint c_unique_all {
    foreach (core_power[i, j])
    foreach (core_power[i2, j2])
    if ((i * 3 + j) < (i2 * 3 + j2)) core_power[i][j] != core_power[i2][j2];
  }

  constraint c_rowsum {
    foreach (core_power[i]) core_power[i][0] + core_power[i][1] + core_power[i][2] == 15;
