class sb extends uvm_component;
  `uvm_component_utils(sb)

  uvm_analysis_imp_expected #(xaction, sb) expected_export;
  uvm_analysis_imp_actual #(xaction, sb) actual_export;

  int match_count = 0;
  int mismatch_count = 0;

  function new(string name, uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    expected_export = new("expected_export", this);
    actual_export   = new("actual_export", this);
  endfunction

  xaction pending_expected[int][$];
  xaction pending_actual[int]  [$];

  virtual function void write_expected(xaction t);
    if (pending_actual.exists(t.id) && pending_actual[t.id].size() > 0) begin
      xaction other = pending_actual[t.id].pop_front();
      if (other.data == t.data) match_count++;
      else mismatch_count++;
    end else begin
      pending_expected[t.id].push_back(t);
    end
  endfunction

  virtual function void write_actual(xaction t);
    if (pending_expected.exists(t.id) && pending_expected[t.id].size() > 0) begin
      xaction other = pending_expected[t.id].pop_front();
      if (other.data == t.data) match_count++;
      else mismatch_count++;
    end else begin
      pending_actual[t.id].push_back(t);
    end
  endfunction

  virtual function int pending_count();
    int total;
    foreach (pending_expected[id]) total += pending_expected[id].size();
    foreach (pending_actual[id]) total += pending_actual[id].size();
    return total;
  endfunction

endclass

